def get_odd_collatz(n):
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    def collatz_sequence(num):
        while num != 1:
            yield num
            num = num // 2 if num % 2 == 0 else num * 3 + 1

    return sorted(set(num for num in collatz_sequence(n) if num % 2 == 1) + [1])
